/**
 * Post-processes the OpenAPI specification generated by `protoc-gen-connect-openapi`
 * into a clean OpenAPI 3.2.0 document, merges `grpc.health.v1.Health` routes with
 * unauthenticated `security: []`, removes empty PathItems, cleans empty stub files,
 * and emits `openapi/puppet.openapi.json` and `src/openapi-spec.ts`.
 */
import { readFile, rm, writeFile } from 'node:fs/promises'
import path from 'node:path'

export interface OpenApiDocument {
  openapi: string
  info: {
    title: string
    version: string
    description?: string
    [key: string]: unknown
  }
  tags?: Array<{ name: string; description?: string; [key: string]: unknown }>
  paths: Record<string, Record<string, unknown>>
  components: {
    securitySchemes?: Record<string, unknown>
    schemas?: Record<string, unknown>
    [key: string]: unknown
  }
  security?: Array<Record<string, unknown>>
  [key: string]: unknown
}

/**
 * Enrich a Connect-generated OpenAPI 3.1 document into OpenAPI 3.2.0,
 * stripping empty PathItems, merging optional Health paths/schemas (with
 * `security: []`), and ensuring all operation tags are declared.
 */
export function enrichOpenApiDocument (
  doc: Partial<OpenApiDocument>,
  version: string,
  healthDoc?: Partial<OpenApiDocument>,
): OpenApiDocument {
  const mergedPaths: Record<string, Record<string, unknown>> = {}
  for (const [route, item] of Object.entries(doc.paths ?? {})) {
    if (item && typeof item === 'object' && Object.keys(item).length > 0) {
      mergedPaths[route] = item
    }
  }
  for (const [route, item] of Object.entries(healthDoc?.paths ?? {})) {
    if (!item || typeof item !== 'object' || Object.keys(item).length === 0) {
      continue
    }
    if (route in mergedPaths) {
      throw new Error(`OpenAPI path collision on "${route}" while merging healthDoc`)
    }
    const securedItem: Record<string, unknown> = {}
    for (const [method, op] of Object.entries(item)) {
      if (op && typeof op === 'object') {
        securedItem[method] = { ...(op as Record<string, unknown>), security: [] }
      } else {
        securedItem[method] = op
      }
    }
    mergedPaths[route] = securedItem
  }

  const mergedSchemas: Record<string, unknown> = { ...(doc.components?.schemas ?? {}) }
  for (const [name, schema] of Object.entries(healthDoc?.components?.schemas ?? {})) {
    if (name in mergedSchemas) {
      if (JSON.stringify(mergedSchemas[name]) !== JSON.stringify(schema)) {
        throw new Error(`OpenAPI schema collision on "${name}" while merging healthDoc`)
      }
      continue
    }
    mergedSchemas[name] = schema
  }

  const tagSet = new Set<string>()
  for (const item of Object.values(mergedPaths)) {
    for (const op of Object.values(item)) {
      if (op && typeof op === 'object' && Array.isArray((op as { tags?: unknown }).tags)) {
        for (const t of (op as { tags: unknown[] }).tags) {
          if (typeof t === 'string') tagSet.add(t)
        }
      }
    }
  }

  const existingTags = new Map<string, { name: string; description?: string }>()
  for (const t of [...(doc.tags ?? []), ...(healthDoc?.tags ?? [])]) {
    if (t?.name) existingTags.set(t.name, t)
  }
  const tags = Array.from(tagSet).map(name => existingTags.get(name) ?? { name })

  return {
    ...doc,
    openapi: '3.2.0',
    info: {
      title: 'Wechaty Puppet Service API',
      version,
      description: 'Multi-protocol ConnectRPC & OpenAPI 3.2 interface for Wechaty Puppet Service.',
    },
    tags,
    components: {
      ...doc.components,
      schemas: mergedSchemas,
      securitySchemes: {
        ...doc.components?.securitySchemes,
        BearerAuth: {
          type: 'http',
          scheme: 'bearer',
          description: 'Pass WECHATY_PUPPET_SERVICE_TOKEN as Bearer token.',
        },
      },
    },
    security: [{ BearerAuth: [] }],
    paths: mergedPaths,
  }
}

async function main (): Promise<void> {
  const pkgRoot = path.resolve(import.meta.dirname, '..')
  const pkgJsonPath = path.join(pkgRoot, 'package.json')
  const puppetInputPath = path.join(pkgRoot, 'openapi', 'wechaty', 'puppet.openapi.json')
  const healthInputPath = path.join(pkgRoot, 'openapi', 'grpc', 'health', 'v1', 'health.openapi.json')
  const enrichedJsonPath = path.join(pkgRoot, 'openapi', 'puppet.openapi.json')
  const openApiTsPath = path.join(pkgRoot, 'src', 'openapi-spec.ts')

  const pkg = JSON.parse(await readFile(pkgJsonPath, 'utf8')) as { version: string }
  const rawDoc = JSON.parse(await readFile(puppetInputPath, 'utf8')) as Partial<OpenApiDocument>

  let healthDoc: Partial<OpenApiDocument> | undefined
  try {
    healthDoc = JSON.parse(await readFile(healthInputPath, 'utf8')) as Partial<OpenApiDocument>
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code !== 'ENOENT') {
      throw err
    }
  }

  const enriched = enrichOpenApiDocument(rawDoc, pkg.version, healthDoc)
  await writeFile(enrichedJsonPath, `${JSON.stringify(enriched, null, 2)}\n`, 'utf8')

  // Remove raw sub-directories containing empty stub files
  await rm(path.join(pkgRoot, 'openapi', 'wechaty'), { recursive: true, force: true })
  await rm(path.join(pkgRoot, 'openapi', 'grpc'), { recursive: true, force: true })

  const tsOutput = [
    '/** @generated by scripts/enrich-openapi.ts — do not edit manually. */',
    'export interface OpenApiDocument {',
    '  openapi: string',
    '  info: { title: string; version: string; description?: string; [key: string]: unknown }',
    '  tags?: Array<{ name: string; description?: string; [key: string]: unknown }>',
    '  paths: Record<string, Record<string, unknown>>',
    '  components: { securitySchemes?: Record<string, unknown>; schemas?: Record<string, unknown>; [key: string]: unknown }',
    '  security?: Array<Record<string, unknown>>',
    '  [key: string]: unknown',
    '}',
    '',
    `export const openApiSpec: OpenApiDocument = ${JSON.stringify(enriched, null, 2)}`,
    '',
  ].join('\n')
  await writeFile(openApiTsPath, tsOutput, 'utf8')
}

if (import.meta.main) {
  await main()
}
